"""Small shared CUDA preflight for startup and tray model actions."""
import json
from pathlib import Path


def probe(metadata_root):
    """Return (available, reason) without loading or downloading a model."""
    profile = Path(metadata_root) / "config" / "package-profile.json"
    try:
        variant = json.loads(profile.read_text(encoding="utf-8")).get("variant")
    except (OSError, ValueError):
        variant = None
    if variant == "cpu":
        return False, "cuda_backend_unavailable"

    try:
        import ctranslate2
        if ctranslate2.get_cuda_device_count() <= 0:
            return False, "nvidia_gpu_unavailable"
        if "float16" not in ctranslate2.get_supported_compute_types("cuda"):
            return False, "cuda_backend_unavailable"
    except Exception:
        return False, "cuda_backend_unavailable"
    return True, None
